			name: "With+Group wrapping Route+With",
			setup: func() Router {
				r := NewMux()
				r.With(mw).Group(func(r Router) {
					r.Route("/foo", func(r Router) {
						r.With(mw).Post("/bar", handler)
					})
				})
				return r
			},
			expected: 2,
		},
		{
			name: "Use on subrouter combined with outer With",
			setup: func() Router {
				r := NewMux()
				r.With(mw).Group(func(r Router) {
					r.Route("/foo", func(r Router) {
						r.Use(mw)
						r.With(mw).Post("/bar", handler)
					})
				})
				return r
			},
			expected: 3,
